/**
 * Worker entry: the OpenNext (Next.js) handler plus two crons.
 * "0 12 * * *" (12:00 UTC = 09:00 Buenos Aires) runs the daily jobs, each in its own try/catch:
 *  - one push per user for invoices that just became overdue (lib/documents-push.ts),
 *  - creation of due recurring movements (lib/recurring.ts, idempotent) and purge of receipts never attached to a movement,
 *  - Luma calendar sync (lib/luma-sync.ts). A missing LUMA_ICS_URL logs luma_sync_skipped and changes nothing.
 * The second cron, at minute 30 of every 6th hour, runs only the Luma sync.
 */
// Generated by `opennextjs-cloudflare build`; it may or may not exist when `next build` type-checks this file.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "./.open-next/worker.js";
import { notifyOverdueInvoices } from "./lib/documents-push.ts";
import { todayBA } from "./lib/agenda-dates.ts";
import { generateDue, todayInBuenosAires } from "./lib/recurring.ts";
import { purgeOrphanReceipts } from "./lib/receipts-db.ts";
import { WorkerEntrypoint } from "cloudflare:workers";
import { listContactsWithEmail, upsertContactByEmail } from "./lib/mailtox-link.ts";
import { createContact, createEvent, createTask, listContacts, listEvents, listInquiries, listTasks, searchContacts, searchEvents, searchInquiries, searchTasks } from "./lib/mcp-rpc.ts";
import { syncLumaEvents } from "./lib/luma-sync.ts";

type Env = { DB: Parameters<typeof notifyOverdueInvoices>[0] & Parameters<typeof generateDue>[0] & Parameters<typeof purgeOrphanReceipts>[0] & Parameters<typeof syncLumaEvents>[0]; VAPID_PUBLIC_KEY?: string; VAPID_PRIVATE_KEY?: string; MAILTOX_LINK_OWNER_EMAIL?: string; MCP_OWNER_EMAIL?: string; LUMA_ICS_URL?: string };
type Ctx = { waitUntil(p: Promise<unknown>): void };
const ADMIN_EMAIL = "lucianoolivabianco@gmail.com"; // VAPID subject; same value as lib/auth.ts (not imported: it pulls Better Auth into the cron)

async function overdueInvoices(env: Env, now: Date) {
  if (!env.VAPID_PUBLIC_KEY || !env.VAPID_PRIVATE_KEY) return null;
  return notifyOverdueInvoices(env.DB, todayBA(now), { publicKey: env.VAPID_PUBLIC_KEY, privateKey: env.VAPID_PRIVATE_KEY, subject: `mailto:${ADMIN_EMAIL}` });
}

async function recurringAndReceipts(env: Env, now: Date) {
  const result = await generateDue(env.DB, null, todayInBuenosAires(now.getTime()));
  const purged = await purgeOrphanReceipts(env.DB, now.getTime());
  console.log("cron_recurring_done", { rules: result.rules, created: result.created, purgedReceipts: purged });
  return result;
}

async function runLumaSync(env: Env) {
  await syncLumaEvents(env.DB, env.MCP_OWNER_EMAIL, env.LUMA_ICS_URL, fetch);
}

async function runDailyJobs(env: Env, now = new Date()) {
  const jobs: [string, () => Promise<unknown>][] = [["overdue_invoices", () => overdueInvoices(env, now)], ["recurring_and_receipts", () => recurringAndReceipts(env, now)], ["luma_sync", () => runLumaSync(env)]];
  for (const [name, job] of jobs) {
    try { await job(); } catch (error) { console.error("cron_job_failed", { job: name, error: String(error) }); }
  }
}

/** Mailtox service binding. RPC only: this class is not mounted on the default HTTP handler. */
export class MailtoxLink extends WorkerEntrypoint<Env> {
  async listContactsWithEmail(sinceCursor?: string | null) {
    return listContactsWithEmail(this.env.DB, this.env.MAILTOX_LINK_OWNER_EMAIL, sinceCursor);
  }

  async upsertContactByEmail(input: { email: string; name?: string; phone?: string; company?: string }) {
    return upsertContactByEmail(this.env.DB, this.env.MAILTOX_LINK_OWNER_EMAIL, input);
  }
}

/** lulox-mcp service binding. RPC only: this class is not mounted on the default HTTP handler. */
export class McpRpc extends WorkerEntrypoint<Env> {
  listContacts(input: unknown) {
    return listContacts(this.env.DB, this.env.MCP_OWNER_EMAIL, input);
  }

  searchContacts(input: unknown) {
    return searchContacts(this.env.DB, this.env.MCP_OWNER_EMAIL, input);
  }

  createContact(input: unknown) {
    return createContact(this.env.DB, this.env.MCP_OWNER_EMAIL, input);
  }

  listTasks(input: unknown) {
    return listTasks(this.env.DB, this.env.MCP_OWNER_EMAIL, input);
  }

  searchTasks(input: unknown) {
    return searchTasks(this.env.DB, this.env.MCP_OWNER_EMAIL, input);
  }

  createTask(input: unknown) {
    return createTask(this.env.DB, this.env.MCP_OWNER_EMAIL, input);
  }

  listEvents(input: unknown) {
    return listEvents(this.env.DB, this.env.MCP_OWNER_EMAIL, input);
  }

  searchEvents(input: unknown) {
    return searchEvents(this.env.DB, this.env.MCP_OWNER_EMAIL, input);
  }

  createEvent(input: unknown) {
    return createEvent(this.env.DB, this.env.MCP_OWNER_EMAIL, input);
  }

  listInquiries(input: unknown) {
    return listInquiries(this.env.DB, this.env.MCP_OWNER_EMAIL, input);
  }

  searchInquiries(input: unknown) {
    return searchInquiries(this.env.DB, this.env.MCP_OWNER_EMAIL, input);
  }
}

const worker = {
  fetch(request: Request, env: unknown, ctx: unknown) {
    return handler.fetch(request, env, ctx);
  },
  async scheduled(event: { cron?: string }, env: Env, ctx: Ctx) {
    if (event.cron === "30 */6 * * *") {
      ctx.waitUntil(runLumaSync(env).catch((error: unknown) => { console.error("cron_job_failed", { job: "luma_sync", error: String(error) }); }));
      return;
    }
    ctx.waitUntil(runDailyJobs(env));
  },
};

export default worker;
